export function projectContext(): ActionContext {
    return { kind: 'project' }
}

/** Build context for a top-level or drill-down diagram action. */
export function diagramContext(type: 'root'): ActionContext
export function diagramContext(type: 'root', diagramId: string, diagramChanges: string, diagramChangeSetId: string): ActionContext
export function diagramContext(type: 'child', diagramId: string, diagramItemId: string, parentNode: string): ActionContext
export function diagramContext(
    type: 'child' | 'root',
    diagramId?: string,
    diagramItemIdOrChanges?: string,
    parentNodeOrChangeSetId?: string,
): ActionContext {
    if (type === 'root') {
        if (
            diagramId === undefined
            && diagramItemIdOrChanges === undefined
            && parentNodeOrChangeSetId === undefined
        ) return { kind: 'diagram', type }
        if (!diagramId || !diagramItemIdOrChanges || !parentNodeOrChangeSetId) {
            throw new Error('Reviewed diagram context requires diagram, change-set, and change values')
        }

        return {
            diagramChanges: diagramItemIdOrChanges,
            diagramChangeSetId: parentNodeOrChangeSetId,
            diagramId,
            kind: 'diagram',
            type,
        }
    }
    if (!diagramId || !diagramItemIdOrChanges || !parentNodeOrChangeSetId) {
        throw new Error('Child diagram context requires diagram, item, and parent-node values')
    }

    return { diagramId, diagramItemId: diagramItemIdOrChanges, kind: 'diagram', parentNode: parentNodeOrChangeSetId, type }
}

/** Add or remove the session assignment used by project-wide popup actions. */
export function projectContextWithWorktree(context: ActionContext, worktree: number | null, worktreeBranch: string | null): ActionContext {
    if (context.kind !== 'project') return context
    if (worktree === null) {
        const unassignedContext = { ...context }
        delete unassignedContext.worktree
        delete unassignedContext.worktreeBranch;

        return unassignedContext
    }

    return { ...context, worktree: String(worktree), worktreeBranch: worktreeBranch === null ? undefined : worktreeBranch };
}

/**
 * True when the action is allowed in the given context. An action with no
 * `appliesTo` (like the built-in custom prompt) matches every context; otherwise
 * every `appliesTo` key must equal the same field on the context.
 */
export function actionMatchesContext(action: ActionDefinition, context: ActionContext): boolean {
    if (!action.appliesTo) return true
    const currentContext = action.appliesTo.worktree === undefined
        ? context : contextWithCurrentWorktree(context, worktreeService.getRecords());
    if (action.appliesTo.worktree !== undefined && currentContext.worktreeError) return false;
    if (action.appliesTo.worktree !== undefined && (context.kind === 'card' || context.kind === 'file') && currentContext.worktree) {
        const assignment = { branch: currentContext.worktreeBranch, worktree: Number(currentContext.worktree) };
        if (worktreeService.getAssignmentState(assignment).error) return false;
    }

    return ACTION_APPLIES_TO_FIELDS.every((key) => action.appliesTo?.[key] === undefined || currentContext[key] === action.appliesTo[key]);
}

/** All actions that should be shown for a context, preserving load order. */
export function actionsForContext(actions: ActionDefinition[], context: ActionContext): ActionDefinition[] {
    if (context.kind === 'diagram') {
        return actions.filter((action) => (
            !action.builtin
            && action.appliesTo?.kind === 'diagram'
            && actionMatchesContext(action, context)
        ))
    }

    return actions.filter((action) => (!action.builtin || action.id === CUSTOM_PROMPT_ACTION_ID) && actionMatchesContext(action, context))

import { useSyncExternalStore } from 'react'
import {
    ACTIONS_CHANGED_EVENT,
    actionService,
    type ActionService,
    type ActionServiceState,
} from '../../services/actions/action_service'

const snapshots = new WeakMap<ActionService, ActionServiceState>()

function isSameActionServiceState(first: ActionServiceState, second: ActionServiceState) {
    return first.actions === second.actions && first.error === second.error
}

function getActionServiceSnapshot(service: ActionService): ActionServiceState {
    const nextSnapshot = service.getState()
    const currentSnapshot = snapshots.get(service)
    if (currentSnapshot && isSameActionServiceState(currentSnapshot, nextSnapshot)) return currentSnapshot

    snapshots.set(service, nextSnapshot)

    return nextSnapshot
}

/** Subscribe to the loaded action definitions exposed by the action service. */
export function useActions(service: ActionService = actionService): ActionServiceState {
    return useSyncExternalStore(
        (onStoreChange) => {
            service.addEventListener(ACTIONS_CHANGED_EVENT, onStoreChange)

            return () => service.removeEventListener(ACTIONS_CHANGED_EVENT, onStoreChange)
        },
        () => getActionServiceSnapshot(service),
        () => getActionServiceSnapshot(service),
    )
}

